// Visual baselines (#73) for the memory screen in light and dark at 360, 768 and 1280 px.
// Baselines are generated by the Playwright visual job in CI; never run locally.
import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

const MEMORY = '/w/chennai-solo/memory';
const WIDTHS = [360, 768, 1280] as const;

for (const colorScheme of ['light', 'dark'] as const) {
  for (const width of WIDTHS) {
    test(`memory ${colorScheme} ${String(width)}`, async ({ page, asUser }) => {
      await page.setViewportSize({ width, height: 900 });
      await page.emulateMedia({ colorScheme });
      await asUser('owner', { path: `${MEMORY}?__state=empty` });
      await shellReady(page);
      await expect(page).toHaveScreenshot(`memory-${colorScheme}-${String(width)}.png`, {
        fullPage: true,
      });
    });
  }
}
